{
  "version": 1,
  "violations": []
}

/**
 * DF Manager — deterministic Dark Factory watchdog.
 *
 * Audits Jira labels, GitHub PRs, and workflow runs for stuck automation states.
 * By default it is read-only and writes outputs/df_manager_report.json.
 * Set customParams.autoRecover=true to execute safe recovery actions.
 */

var configLoader = require('./configLoader.js');
var scmModule = require('./common/scm.js');
var trackersModule = require('./common/trackers.js');

var DEFAULT_SM_LABELS = [
    'sm_story_ba_check_triggered',
    'sm_story_acceptance_criteria_triggered',
    'sm_story_acceptance_criterias_triggered',
    'sm_story_solution_triggered',
    'sm_po_refinement_triggered',
    'sm_story_questions_triggered',
    'sm_task_intake_triggered',
    'sm_story_development_triggered',
    'sm_bug_development_triggered',
    'sm_bug_creation_triggered',
    'sm_story_review_triggered',
    'sm_pr_review_triggered',
    'sm_story_rework_triggered',
    'sm_pr_rework_triggered',
    'sm_pr_merge_triggered',
    'sm_test_cases_triggered',
    'sm_bug_merged_triggered',
    'sm_bug_test_cases_triggered',
    'sm_story_done_check_triggered',
    'sm_bug_done_check_triggered',
    'sm_task_done_check_triggered',
    'sm_test_automation_triggered',
    'sm_test_review_triggered',
    'sm_test_rework_triggered'
];

function parseJsonMaybe(value, fallback) {
    if (value === null || value === undefined || value === '') return fallback;
    if (typeof value !== 'string') return value;
    try { return JSON.parse(value); } catch (e) { return fallback; }
}

// Container keys used by tracker/SCM list responses (Jira paged values, ADO
// work items, GitHub workflow runs / composite results). Kept in priority order.
var ARRAY_CONTAINER_KEYS = ['values', 'items', 'workflow_runs', 'result'];

// Pure: return the first container key of `value` that holds an array, else null.
function firstArrayContainer(value) {
    for (var i = 0; i < ARRAY_CONTAINER_KEYS.length; i++) {
        var candidate = value[ARRAY_CONTAINER_KEYS[i]];
        if (Array.isArray(candidate)) return candidate;
    }
    return null;
}

function asArray(value) {
    if (!value) return [];
    if (Array.isArray(value)) return value;
    return firstArrayContainer(value) || [];
}

function uniq(values) {
    var seen = {};
    return (values || []).filter(function(value) {
        if (!value || seen[value]) return false;
        seen[value] = true;
        return true;
    });
}

function normalizeLabelNames(labels) {
    return (labels || []).map(function(label) {
        return typeof label === 'string' ? label : (label && label.name);
    }).filter(function(label) { return !!label; });
}

function ticketStatus(ticket) {
    return ticket && ticket.fields && ticket.fields.status && ticket.fields.status.name || '';
}

function ticketLabels(ticket) {
    return normalizeLabelNames(ticket && ticket.fields && ticket.fields.labels || []);
}

function ticketUpdatedAt(ticket) {
    return ticket && ticket.fields && ticket.fields.updated || ticket && ticket.updated || null;
}

function ticketAgeMinutes(ticket, nowMs) {
    var updated = ticketUpdatedAt(ticket);
    if (!updated) return null;
    var parsed = Date.parse(updated);
    if (isNaN(parsed)) return null;
    return Math.floor((nowMs - parsed) / 60000);
}

function prLabels(pr) {
    return normalizeLabelNames(pr && pr.labels || []);
}

function prHeadRef(pr) {
    return pr && pr.head && pr.head.ref || pr && pr.headRefName || pr && pr.sourceBranch || '';
}

function prTitle(pr) {
    return pr && pr.title || '';
}

function prMergeState(pr) {
    return pr && (pr.mergeable_state || pr.mergeStateStatus || pr.merge_state_status || '').toString().toLowerCase();
}

function prUrl(pr) {
    return pr && (pr.html_url || pr.url || pr.web_url) || '';
}

function extractTicketKey(text) {
    var match = String(text || '').match(/[A-Z][A-Z0-9]+-\d+/);
    return match ? match[0] : null;
}

function runText(run) {
    return [
        run && run.name,
        run && run.display_title,
        run && run.displayTitle,
        run && run.head_branch,
        run && run.headBranch,
        run && run.workflowName,
        run && run.event
    ].filter(function(part) { return !!part; }).join(' ');
}

function runStatus(run) {
    return (run && run.status || '').toString().toLowerCase();
}

function runConclusion(run) {
    return (run && run.conclusion || '').toString().toLowerCase();
}

function runUrl(run) {
    return run && (run.html_url || run.url) || '';
}

// Run statuses that mean "a runner is (or will be) behind this run" — the
// ACTIVE vocabulary shared by every workflow-run liveness check below.
// A set-style list keeps isActiveRun branch-free (CC 1); membership and
// casing semantics are identical to the former ||-chain.
var ACTIVE_RUN_STATUSES = ['queued', 'pending', 'requested', 'waiting', 'in_progress'];

function isActiveRun(run) {
    return ACTIVE_RUN_STATUSES.indexOf(runStatus(run)) !== -1;
}

function isFailedRun(run) {
    return runStatus(run) === 'completed' && runConclusion(run) === 'failure';
}

function activeRunMatchesTicket(activeRuns, ticketKey) {
    return activeRuns.some(function(run) {
        return runText(run).indexOf(ticketKey) !== -1;
    });
}

function collectLabelsFromRules(rules) {
    var labels = [];
    (rules || []).forEach(function(rule) {
        if (!rule || rule.enabled === false) return;
        if (rule.addLabel) labels.push(rule.addLabel);
        if (rule.skipIfLabel) labels.push(rule.skipIfLabel);
        (rule.addLabels || []).forEach(function(label) { labels.push(label); });
        (rule.skipIfLabels || []).forEach(function(label) { labels.push(label); });
    });
    return labels;
}

function extractStatusesFromJql(jql) {
    var text = String(jql || '');
    var statuses = [];
    var inMatch = text.match(/status\s+in\s*\(([^)]+)\)/i);
    if (inMatch) {
        statuses = inMatch[1].split(',').map(function(item) {
            return item.replace(/^['"\s]+|['"\s]+$/g, '');
        }).filter(function(item) { return !!item; });
    }
    var eqMatch = text.match(/status\s*=\s*['"]?([^'")\s]+(?:\s+[^'")]+)*)['"]?/i);
    if (!statuses.length && eqMatch) {
        statuses = [eqMatch[1].trim()];
    }
    return statuses;
}

function extractExcludedStatusesFromJql(jql) {
    var text = String(jql || '');
    var statuses = [];
    var notInMatch = text.match(/status\s+not\s+in\s*\(([^)]+)\)/i);
    if (notInMatch) {
        statuses = notInMatch[1].split(',').map(function(item) {
            return item.replace(/^['"\s]+|['"\s]+$/g, '');
        }).filter(function(item) { return !!item; });
    }
    return statuses;
}

function buildLabelStatusMap(rules) {
    var map = {};
    (rules || []).forEach(function(rule) {
        if (!rule || rule.enabled === false) return;
        var labels = [];
        if (rule.addLabel) labels.push(rule.addLabel);
            if (rule.skipIfLabel) labels.push(rule.skipIfLabel);
            (rule.addLabels || []).forEach(function(label) { labels.push(label); });
            (rule.skipIfLabels || []).forEach(function(label) { labels.push(label); });
        var includeStatuses = extractStatusesFromJql(rule.jql);
        var excludeStatuses = extractExcludedStatusesFromJql(rule.jql);
        labels.forEach(function(label) {
            if (!map[label]) map[label] = { include: [], exclude: [] };
            map[label].include = uniq(map[label].include.concat(includeStatuses));
            map[label].exclude = uniq(map[label].exclude.concat(excludeStatuses));
        });
    });
    return map;
}

function isLabelActiveForStatus(labelStatusRule, status) {
    if (!labelStatusRule) return true;
    var include = labelStatusRule.include || [];
    var exclude = labelStatusRule.exclude || [];
    if (exclude.indexOf(status) !== -1) return false;
    if (include.length > 0) return include.indexOf(status) !== -1;
    return true;
}

function loadSmRules(params) {
    if (params.rules && Array.isArray(params.rules)) return params.rules;
    if (params.smRules && Array.isArray(params.smRules)) return params.smRules;
    try {
        var raw = file_read({ path: params.smConfigPath || 'agents/sm.json' });
        var parsed = JSON.parse(raw);
        return parsed && parsed.params && parsed.params.jobParams && parsed.params.jobParams.rules || [];
    } catch (e) {
        console.warn('DF Manager: could not read sm rules:', e.message || e);
        return [];
    }
}

function resolveSmLabels(params, rules) {
    return uniq([].concat(
        DEFAULT_SM_LABELS,
        collectLabelsFromRules(rules),
        params.smLabels || []
    ));
}

function buildSmLabelJql(projectKey, labels) {
    var quoted = labels.map(function(label) { return '"' + String(label).replace(/"/g, '\\"') + '"'; });
    return 'project = ' + projectKey + ' AND labels in (' + quoted.join(', ') + ') ORDER BY updated ASC';
}

function searchJiraTickets(projectKey, labels, limit, tracker) {
    if (!labels.length) return [];
    var jql = buildSmLabelJql(projectKey, labels);
    // JQL text: provider-specific query (WIQL on ado)
    var result = tracker.searchIssues(jql, {
        fields: ['summary', 'status', 'labels', 'updated', 'issuetype'],
        maxResults: limit || 100
    });
    return asArray(parseJsonMaybe(result, result));
}

function listWorkflowRuns(scm, status, limit) {
    try {
        return asArray(parseJsonMaybe(scm.listWorkflowRuns(status, null, limit || 100), []));
    } catch (e) {
        console.warn('DF Manager: could not list workflow runs for status ' + status + ':', e.message || e);
        return [];
    }
}

function listOpenPrs(scm) {
    try {
        return asArray(parseJsonMaybe(scm.listPrs('open'), []));
    } catch (e) {
        console.warn('DF Manager: could not list open PRs:', e.message || e);
        return [];
    }
}

function appendAnomaly(anomalies, item) {
    anomalies.push(item);
    console.log('DF anomaly [' + item.severity + '] ' + item.type + (item.ticketKey ? ' ' + item.ticketKey : '') +
        (item.prNumber ? ' PR #' + item.prNumber : '') + ': ' + item.message);
}

function detectStaleSmLabels(context) {
    var staleMinutes = context.staleMinutes;
    context.tickets.forEach(function(ticket) {
        var key = ticket.key;
        if (!key) return;
        var status = ticketStatus(ticket);
        var labels = ticketLabels(ticket).filter(function(label) {
            return context.smLabelSet[label] === true;
        });
        if (!labels.length) return;
        if (activeRunMatchesTicket(context.activeRuns, key)) return;

        var age = ticketAgeMinutes(ticket, context.nowMs);
        var isOldEnough = age === null || age >= staleMinutes;
        if (!isOldEnough) return;

        var sourceStateLabels = labels.filter(function(label) {
            return isLabelActiveForStatus(context.labelStatusMap[label], status);
        });
        if (!sourceStateLabels.length) {
            appendAnomaly(context.anomalies, {
                type: 'obsolete-sm-label',
                severity: 'info',
                ticketKey: key,
                status: status,
                labels: labels,
                ageMinutes: age,
                safeAction: 'remove-sm-labels',
                message: 'SM trigger label remains after the ticket moved out of the rule source status.'
            });
            return;
        }

        appendAnomaly(context.anomalies, {
            type: 'stale-sm-label',
            severity: 'blocking',
            ticketKey: key,
            status: status,
            labels: sourceStateLabels,
            ageMinutes: age,
            safeAction: 'remove-sm-labels-and-trigger-sm',
            message: 'SM trigger label exists but no active workflow run contains the ticket key.'
        });
    });
}

function detectPrMergeGaps(context) {
    context.prs.forEach(function(pr) {
        var key = extractTicketKey(prTitle(pr) + ' ' + prHeadRef(pr));
        var labels = prLabels(pr);
        var state = prMergeState(pr);
        var number = pr.number || pr.pullRequestId || pr.id;
        if (!key || !number) return;

        var ticket = context.ticketByKey[key];
        var jiraLabels = ticket ? ticketLabels(ticket) : [];
        var hasApproval = labels.indexOf('pr_approved') !== -1 || jiraLabels.indexOf('pr_approved') !== -1;

        if (hasApproval && (state === 'clean' || state === 'mergeable')) {
            appendAnomaly(context.anomalies, {
                type: 'approved-pr-not-merged',
                severity: 'blocking',
                ticketKey: key,
                prNumber: number,
                prUrl: prUrl(pr),
                mergeState: state,
                safeAction: 'trigger-sm-retry-merge',
                message: 'PR is approved and clean but still open.'
            });
        } else if (hasApproval && (state === 'dirty' || state === 'behind')) {
            appendAnomaly(context.anomalies, {
                type: 'approved-pr-not-mergeable',
                severity: 'warning',
                ticketKey: key,
                prNumber: number,
                prUrl: prUrl(pr),
                mergeState: state,
                safeAction: state === 'behind' ? 'request-branch-update' : null,
                message: 'PR is approved but not currently mergeable.'
            });
        }
    });
}

function detectFailedRuns(context) {
    context.failedRuns.forEach(function(run) {
        var key = extractTicketKey(runText(run));
        appendAnomaly(context.anomalies, {
            type: 'failed-workflow-run',
            severity: 'warning',
            ticketKey: key,
            runUrl: runUrl(run),
            workflow: run.workflowName || run.name || '',
            message: 'Recent workflow run failed.'
        });
    });
}

function detectDuplicateRuns(context) {
    var grouped = {};
    context.activeRuns.forEach(function(run) {
        var key = extractTicketKey(runText(run));
        if (!key) return;
        if (!grouped[key]) grouped[key] = [];
        grouped[key].push(run);
    });
    Object.keys(grouped).forEach(function(key) {
        if (grouped[key].length <= 1) return;
        appendAnomaly(context.anomalies, {
            type: 'duplicate-active-runs',
            severity: 'warning',
            ticketKey: key,
            runUrls: grouped[key].map(runUrl).filter(function(url) { return !!url; }),
            message: 'Multiple active workflow runs reference the same ticket.'
        });
    });
}

function detectRepeatedFailureLoops(context) {
    var grouped = {};

    context.failedRuns.forEach(function(run) {
        var key = extractTicketKey(runText(run));
        if (!key) return;
        if (!grouped[key]) {
            grouped[key] = {
                total: 0,
                workflows: {},
                urls: []
            };
        }

        var bucket = grouped[key];
        var workflow = run.workflowName || run.name || 'unknown-workflow';
        bucket.total += 1;
        bucket.workflows[workflow] = (bucket.workflows[workflow] || 0) + 1;
        var url = runUrl(run);
        if (url) bucket.urls.push(url);
    });

    Object.keys(grouped).forEach(function(key) {
        var bucket = grouped[key];
        if (bucket.total < 3) return;

        var ticket = context.ticketByKey[key];
        var status = ticketStatus(ticket);
        var labelCount = ticketLabels(ticket).filter(function(label) {
            return context.smLabelSet[label] === true;
        }).length;
        var workflows = Object.keys(bucket.workflows).map(function(name) {
            return name + '×' + bucket.workflows[name];
        }).join(', ');

        appendAnomaly(context.anomalies, {
            type: 'repeated-failure-loop',
            severity: (status === 'Failed' || labelCount > 0 || bucket.total >= 5) ? 'blocking' : 'warning',
            ticketKey: key,
            workflowRuns: bucket.total,
            workflows: bucket.workflows,
            runUrls: uniq(bucket.urls),
            status: status,
            message: 'Ticket has ' + bucket.total + ' failed workflow runs' +
                (workflows ? ' (' + workflows + ')' : '') +
                (status ? ' while still in ' + status + '.' : '.')
        });
    });
}

function triggerSmWorkflow(context, reason) {
    if (context.recoveryState.smTriggered) return;
    context.scm.triggerWorkflow(
        context.repoInfo.owner,
        context.repoInfo.repo,
        context.params.smWorkflowFile || 'sm.yml',
        '{}',
        context.params.workflowRef || configLoader.resolveDefaultWorkflowRef(null, context.config, null)
    );
    context.recoveryState.smTriggered = true;
    context.actions.push({ action: 'trigger-sm', reason: reason || 'df-manager' });
}

function applySafeRecovery(context) {
    if (!context.autoRecover) return;
    context.anomalies.forEach(function(anomaly) {
        if (anomaly.type === 'stale-sm-label' || anomaly.type === 'obsolete-sm-label') {
            (anomaly.labels || []).forEach(function(label) {
                context.tracker.removeLabel(anomaly.ticketKey, label);
                context.actions.push({ action: 'remove-label', ticketKey: anomaly.ticketKey, label: label });
            });
            if (anomaly.type === 'obsolete-sm-label') return;
            triggerSmWorkflow(context, 'released stale SM label for ' + anomaly.ticketKey);
        } else if (anomaly.type === 'approved-pr-not-merged') {
            triggerSmWorkflow(context, 'retry merge for approved PR #' + anomaly.prNumber);
        } else if (anomaly.type === 'approved-pr-not-mergeable' && anomaly.safeAction === 'request-branch-update') {
            try {
                cli_execute_command({
                    command: 'gh api repos/' + context.repoInfo.owner + '/' + context.repoInfo.repo +
                        '/pulls/' + anomaly.prNumber + '/update-branch -X PUT'
                });
                context.actions.push({ action: 'request-branch-update', prNumber: anomaly.prNumber });
            } catch (e) {
                context.actions.push({
                    action: 'request-branch-update-failed',
                    prNumber: anomaly.prNumber,
                    error: e.message || String(e)
                });
            }
        }
    });
}

function writeReport(path, report) {
    var content = JSON.stringify(report, null, 2);
    try {
        file_write({ path: path, content: content });
    } catch (e) {
        file_write(path, content);
    }
}

function buildContext(params, config, scm, tracker) {
    var rules = loadSmRules(params);
    var labels = resolveSmLabels(params, rules);
    var labelSet = {};
    labels.forEach(function(label) { labelSet[label] = true; });
    var projectKey = params.jiraProject || config.jira && config.jira.project;
    if (!projectKey) throw new Error('DF Manager requires jira.project in config or customParams.jiraProject');

    var activeRuns = []
        .concat(listWorkflowRuns(scm, 'queued', params.workflowRunLimit))
        .concat(listWorkflowRuns(scm, 'in_progress', params.workflowRunLimit))
        .concat(listWorkflowRuns(scm, 'waiting', params.workflowRunLimit));
    var failedRuns = listWorkflowRuns(scm, 'completed', params.workflowRunLimit)
        .filter(isFailedRun)
        .slice(0, params.failedRunLimit || 20);
    var tickets = searchJiraTickets(projectKey, labels, params.jiraLimit || 100, tracker);
    var ticketByKey = {};
    tickets.forEach(function(ticket) { if (ticket && ticket.key) ticketByKey[ticket.key] = ticket; });

    return {
        params: params,
        config: config,
        scm: scm,
        tracker: tracker,
        repoInfo: (config.repository || scm.getRemoteRepoInfo() || {}),
        nowMs: params.nowMs || Date.now(),
        staleMinutes: params.staleMinutes || 45,
        smLabels: labels,
        smLabelSet: labelSet,
        labelStatusMap: buildLabelStatusMap(rules),
        tickets: tickets,
        ticketByKey: ticketByKey,
        prs: listOpenPrs(scm),
        activeRuns: activeRuns,
        failedRuns: failedRuns,
        anomalies: [],
        actions: [],
        autoRecover: params.autoRecover === true,
        recoveryState: {}
    };
}

function action(params) {
    var p = (params.jobParams && params.jobParams.customParams) || params.customParams || params.jobParams || params || {};
    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var scm = scmModule.createScm(config);
    var tracker = trackersModule.createTracker(config, p);
    var context = buildContext(p, config, scm, tracker);

    if (!context.repoInfo.owner || !context.repoInfo.repo) {
        throw new Error('DF Manager requires repository.owner/repo in config or an SCM remote.');
    }

    detectStaleSmLabels(context);
    detectPrMergeGaps(context);
    detectFailedRuns(context);
    detectDuplicateRuns(context);
    detectRepeatedFailureLoops(context);
    applySafeRecovery(context);

    var report = {
        success: true,
        mode: context.autoRecover ? 'safe-recover' : 'audit',
        repository: context.repoInfo,
        jiraProject: p.jiraProject || config.jira && config.jira.project,
        counts: {
            smLabels: context.smLabels.length,
            ticketsWithSmLabels: context.tickets.length,
            openPrs: context.prs.length,
            activeRuns: context.activeRuns.length,
            failedRuns: context.failedRuns.length,
            anomalies: context.anomalies.length,
            actions: context.actions.length
        },
        anomalies: context.anomalies,
        actions: context.actions
    };
    writeReport(p.outputPath || 'outputs/df_manager_report.json', report);
    return report;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        asArray: asArray,
        buildSmLabelJql: buildSmLabelJql,
        collectLabelsFromRules: collectLabelsFromRules,
        extractTicketKey: extractTicketKey,
        detectStaleSmLabels: detectStaleSmLabels,
        detectPrMergeGaps: detectPrMergeGaps,
        detectDuplicateRuns: detectDuplicateRuns,
        buildLabelStatusMap: buildLabelStatusMap,
        extractStatusesFromJql: extractStatusesFromJql,
        extractExcludedStatusesFromJql: extractExcludedStatusesFromJql,
        isActiveRun: isActiveRun
    };
}

/**
 * Check-run zombies (gh-842) — the gate-ghost classifier.
 *
 * Live fa #1457 (2026-10-10, head 7d00a1b2, ~14:30→16:00Z): a dispatched CI
 * run was CANCELLED while queued (gh-748 twin-guard family) and later ceased
 * to exist; the `in_progress` check runs it had registered on the head were
 * never concluded. Branch protection takes the LATEST check-run per
 * (context, head), so the ghosts held mergeStateStatus=BLOCKED for ~2h even
 * though the head ALSO carried terminal GREEN entries from the earlier run
 * 38057801418 (green, 13:58). The tick's green-cover guard (skipIfGreenCi)
 * read the surviving green run as covering the head — "the blocker is not
 * this CI" — and never re-dispatched; the window idled until an operator
 * nudged a fresh dispatch. The gh-821 zombie sweep missed it because the
 * dispatched-RUN probe reads green (the newest EXISTING run is the old
 * green one) — gh-821 classifies runs, gh-842 classifies the check-RUN
 * ghosts those dead runs leave on the gate.
 *
 * This module is the pure half of the fix:
 *
 *   classify(checkRuns, resolveRun, nowMs, opts)
 *                      — partition a head's check-runs: every PENDING
 *                      (queued/in_progress, no conclusion) check-run whose
 *                      backing workflow run is ABSENT (deleted/404),
 *                      concluded CANCELLED, concluded non-cancelled past a
 *                      short propagation grace, or link-less and stale past
 *                      the no-runner threshold, is a ZOMBIE. Everything
 *                      else — concluded checks, live runs, fresh stamps,
 *                      probe errors — is LIVE (AC2: a genuinely in-progress
 *                      run is NEVER disturbed; every unprovable case fails
 *                      SAFE toward live, a missed zombie retries next tick
 *                      while a wrongful re-dispatch burns CI).
 *   runIdOf(checkRun)  — the backing workflow-run id parsed out of
 *                      details_url/html_url (`/actions/runs/<id>`); bridge
 *                      stamps dispatched without a run URL carry none.
 *
 * A zombie's context counts as ABSENT (gh-921 semantics) in the caller: the
 * surviving evidence decides the real rollup, and the caller re-dispatches
 * validation so the fresh stamps become the LATEST per context and override
 * the ghosts on the gate.
 *
 * Pure functions, no tool globals — smAgent wires the transport (the
 * bridge check-runs tool + the head run list as the resolver's source),
 * tests inject nothing. CommonJS module like every other js/ module.
 * GraalJS rules apply: var + plain functions only.
 */

'use strict';

// A check-run is PENDING when GitHub reports it queued/in-flight and no
// conclusion has landed. The settled vocabulary (concluded check-runs) is
// never zombie material — a green terminal entry next to a ghost stays
// green evidence for the surviving rollup.
var PENDING_STATUSES = ['queued', 'in_progress', 'waiting', 'pending', 'requested'];

// Run states that mean "a runner is (or will be) behind this" — the AC2
// vocabulary, same live-run bias as validationLiveness.ACTIVE_RUN_STATES
// plus GitHub's 'requested' pre-queue state.
var ACTIVE_RUN_STATES = ['queued', 'in_progress', 'waiting', 'pending', 'requested'];

// Defaults (jobParams-tunable at the smAgent call site):
//  - a link-less bridge stamp older than 30 min with no runner behind it is
//    a ghost (a live dispatch concludes/updates its stamp well inside that);
//  - a check run whose backing run concluded non-cancelled inside 5 min is
//    still propagating its conclusion (lag, not a ghost).
var DEFAULT_STALE_NO_RUNNER_MINUTES = 30;
var DEFAULT_RUN_CONCLUDED_GRACE_MINUTES = 5;

// ── Placeholders (gh-852) ────────────────────────────────────────────────────
//
// The no-cancel variant of the gate ghost (live fa #1457, 2026-10-11, head
// d29efb16 + 3 predecessors): GitHub mints PENDING placeholder check-runs
// ~20s after a dispatch that queued without materializing a job; their
// html_url carries NO numeric run id. Orphaned when the real run never
// stamps their context, they pin mergeStateStatus=BLOCKED (branch
// protection takes the LATEST check-run per (context, head)) even with
// every real check green. A same-sha re-dispatch can NEVER cure them — a
// queued re-dispatch mints FRESH placeholders — so the engine remedy is a
// fresh-sha reset + an immediate-start validation, pool-probed and
// per-PR-window capped (see js/smAgent.js validate_pr).
//
//  - a link-less pending stamp younger than the placeholder grace may be a
//    bridge stamp of a dispatch that JUST fired (its run link lands
//    seconds later) — only AGE past the grace proves no runner is coming;
//  - the reset cap is per PR per window, NOT per head: every reset mints a
//    NEW head, so head-keyed counting would never reach a cap.
var DEFAULT_PLACEHOLDER_MINUTES = 3;
var DEFAULT_PLACEHOLDER_RESET_CAP = 3;
var DEFAULT_PLACEHOLDER_RESET_WINDOW_MS = 2 * 60 * 60 * 1000;

var PLACEHOLDER_MARKER_RE = /\uD83D\uDD01 placeholder reset (\d+)\/(\d+) at (\S+)/g;

function runIdOf(checkRun) {
    if (!checkRun) return null;
    var url = checkRun.details_url || checkRun.detailsUrl ||
              checkRun.html_url || checkRun.htmlUrl || '';
    var m = /\/actions\/runs\/(\d+)/.exec(String(url));
    return m ? m[1] : null;
}

function isPendingCheckRun(checkRun) {
    if (!checkRun || checkRun.conclusion) return false;
    var s = checkRun.status ? String(checkRun.status).toLowerCase() : '';
    return PENDING_STATUSES.indexOf(s) !== -1;
}

function _num(opts, key, dflt) {
    var n = opts ? opts[key] : null;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    return (typeof n === 'number' && !isNaN(n) && n >= 0) ? n : dflt;
}

function _startedAtMs(checkRun) {
    var ts = Date.parse(checkRun.started_at || checkRun.startedAt ||
                        checkRun.created_at || checkRun.createdAt || '');
    return isNaN(ts) ? null : ts;
}

// ── classify: per-check-run decision helpers (gh-1085) ──────────────────────
//
// The partition verdict for ONE check-run is computed by the small pure
// helpers below; classify() itself only tunes the knobs, iterates and
// tallies. Extraction keeps every branch covered by the characterization
// suite (test_checkRunZombies.js) — CRAP = CC at full coverage.

/** A zombie verdict: the caller re-dispatches (runId ghosts) or resets. */
function zombieVerdict(cr, runId, reason) {
    return { kind: 'zombie', zombie: { name: (cr && cr.name) || null, runId: runId, reason: reason } };
}

/** A live verdict; unresolvable marks the probe-error fail-safe (live + retry next tick). */
function liveVerdict(unresolvable) {
    return { kind: 'live', unresolvable: unresolvable === true };
}

// Linked-run decision tree: probe error → live (fail safe), backing run
// absent → 'no-run' zombie, everything else by the run's state vocabulary.
function classifyLinkedRun(cr, runId, resolveRun, nowMs, graceMs) {
    var state = null;
    var probeError = false;
    try { state = resolveRun(runId); } catch (e) { probeError = true; }
    if (probeError) {
        // Fail SAFE toward live: a missed zombie retries next tick;
        // a wrongful re-dispatch is the churn this guard exists to
        // prevent on healthy heads.
        return liveVerdict(true);
    }
    if (state === null || state === undefined) {
        // The backing run no longer exists (deleted → absent from
        // the head's run list). The #1457 shape: the run was
        // cancelled while queued and later ceased to exist.
        return zombieVerdict(cr, runId, 'no-run');
    }
    return verdictForRunState(cr, runId, state, nowMs, graceMs);
}

// Run-state vocabulary dispatch: ACTIVE → live (AC2), completed → the
// conclusion ladder, unknown vocabulary → live (fail safe).
function verdictForRunState(cr, runId, state, nowMs, graceMs) {
    var st = state.status ? String(state.status).toLowerCase() : '';
    if (ACTIVE_RUN_STATES.indexOf(st) !== -1) {
        return liveVerdict(false);       // AC2 — a runner is (or will be) behind it
    }
    if (st === 'completed') {
        return completedRunVerdict(cr, runId, state, nowMs, graceMs);
    }
    return liveVerdict(false);           // unknown status vocabulary — fail safe
}

// A completed backing run: cancelled → zombie, concluded non-cancelled →
// propagation-lag check, conclusion-less → odd, fail safe toward live.
function completedRunVerdict(cr, runId, state, nowMs, graceMs) {
    var concl = state.conclusion ? String(state.conclusion).toLowerCase() : null;
    if (concl === 'cancelled') {
        return zombieVerdict(cr, runId, 'cancelled');
    }
    if (concl) {
        return concludedRunVerdict(cr, runId, state, nowMs, graceMs);
    }
    return liveVerdict(false);           // completed without a conclusion — odd, fail safe
}

// Non-cancelled conclusion on the backing run: inside the propagation grace
// the conclusion is still landing (live); past it the bridge died mid-stamp.
function concludedRunVerdict(cr, runId, state, nowMs, graceMs) {
    var endTs = Date.parse(state.updated_at || state.created_at || '');
    var lag = isNaN(endTs) ? null : nowMs - endTs;
    if (lag !== null && lag >= 0 && lag <= graceMs) {
        return liveVerdict(false);       // propagation lag — the conclusion is landing
    }
    return zombieVerdict(cr, runId, 'run-concluded');
}

// No run link (dispatch-bridge stamp at arm time carries no details_url):
// staleness is the only liveness evidence. A fresh stamp is a dispatch that
// JUST fired; an old one is a ghost whose run died without concluding it.
// Unparseable/young → fail safe.
function classifyUnlinkedRun(cr, nowMs, staleMs) {
    var started = _startedAtMs(cr || {});
    if (started !== null && (nowMs - started) > staleMs) {
        return zombieVerdict(cr, null, 'stale-no-runner');
    }
    return liveVerdict(false);
}

// One check-run's verdict: settled evidence, a linked-run decision, or the
// link-less staleness decision.
function classifyOne(cr, resolveRun, nowMs, staleMs, graceMs) {
    if (!isPendingCheckRun(cr)) return { kind: 'settled' };

    var runId = runIdOf(cr);
    if (runId !== null && typeof resolveRun === 'function') {
        return classifyLinkedRun(cr, runId, resolveRun, nowMs, graceMs);
    }
    return classifyUnlinkedRun(cr, nowMs, staleMs);
}

// Fold one verdict into the classification output.
function tallyClassifyVerdict(out, verdict) {
    if (verdict.kind === 'zombie') { out.zombies.push(verdict.zombie); return; }
    if (verdict.kind === 'settled') { out.settled++; return; }
    out.live++;
    if (verdict.unresolvable) out.unresolvable++;
}

/**
