    placeholders: placeholders,
    orphanedRunChecks: orphanedRunChecks,
    conclusionForOutcome: conclusionForOutcome,
    openCycle: openCycle,
    closePlaceholderCycle: closePlaceholderCycle,
    zombieSweptLine: zombieSweptLine,
